    for (int i = 1; i <= n; i++) {
        scanf("%lld", &a[i]);
        total_sum += a[i];
        pref[i] = pref[i - 1] + a[i];
    }

    long long *dp_prev = (long long *)malloc((n + 1) * sizeof(long long));
    long long *dp_curr = (long long *)malloc((n + 1) * sizeof(long long));

    for (int i = 0; i <= n; i++) {
        dp_prev[i] = 0;
    }

    for (int j = 1; j <= k; j++) {
        int min_i = j * c;
        int max_i = n - (k - j) * c;

        for (int i = 0; i < min_i; i++) {
            dp_curr[i] = INF;
        }

        for (int i = min_i; i <= max_i; i++) {
            long long seg_sum = pref[i] - pref[i - c];
            long long take = dp_prev[i - c] + seg_sum;
            long long not_take = (i > min_i) ? dp_curr[i - 1] : INF;
            dp_curr[i] = (take < not_take) ? take : not_take;
        }

        for (int i = min_i; i <= max_i; i++) {
            dp_prev[i] = dp_curr[i];
        }
    }

    long long min_covered = dp_curr[n];
